CREATE FUNCTION [dbo].[TAI_FN_agrupacion](@CodLinea int)  RETURNS varchar(50)  AS  BEGIN   declare @agrupacion varchar(50)    set @agrupacion = case @CodLinea        when 109 then 'FERRETERIA'    --Alambres             OK        when 108 then 'ESPECIALIDAD'  --Bioreguladores       OK        when 104 then 'ESPECIALIDAD'  --Esp.Nutri.           OK        when 130 then 'FERRETERIA'    --Ferreteria           OK        when 101 then 'FERTILIZANTE'  --Fertilizantes        OK        when 102 then 'FITOSANITARIO' --Fitosanitarios       OK        when 117 then 'FITOSANITARIO' --Fitosanitarios Prem. OK        when 115 then 'MAQUINARIA'    --Implementos          OK        when 110 then 'FERRETERIA'    --Insumos Varios       OK        when 126 then 'MAQUINARIA'    --Maquinaria Usada     OK        when 113 then 'MAQUINARIA'    --Maquinarias          OK        when 127 then 'MAQUINARIA'    --Maquinarias YTO      OK        when 111 then 'FERRETERIA'    --Plástico Nacional    OK        when 112 then 'FERRETERIA'    --Plásticos Importados OK        when 105 then 'FITOSANITARIO'  --Polisulfuro          OK        when 114 then 'MAQUINARIA'    --Repuestos            OK        when 133 then 'MAQUINARIA'    --Repuestos Nacionales OK        when 128 then 'MAQUINARIA'    --Repuestos YTO        OK        when 103 then 'SEMILLA'       --Semillas             OK        when 116 then 'MAQUINARIA'    --Servicios            OK        when 107 then 'ESPECIALIDAD'  --Surround             OK        when 106 then 'ESPECIALIDAD'  --Sustratos            OK        when 125 then 'MAQUINARIA'    --Tractores            OK        when 131 then 'FERTBLEND'     --Fertblend            OK                      end   RETURN @agrupacion  END
  CREATE VIEW [dbo].[TAI_VW_CabVtas]  AS  /* Facturas Cliente */ SELECT T0.ObjType[ObjType], T0.DocEntry[DocEntry], T0.TransId[TransId], T0.DocNum[DocNum], T0.DocType[DocType], T0.DocSubType[SubType],                         CASE T0.DocSubType WHEN '--' THEN CASE T0.IsIns WHEN 'Y' THEN 'FVR' ELSE 'FV ' END WHEN 'DN' THEN 'NDV' WHEN 'IE' THEN 'FVE' /* Factura Exenta */ WHEN                         'IB' THEN 'BV ' WHEN 'EB' THEN 'BVE' WHEN 'IX' THEN 'FVX' /* Factura Exportación */ WHEN 'IR' THEN 'FVP' /* Factura y Pago */ WHEN 'IB' THEN 'BV ' WHEN 'RI' THEN                         'FVR' /* Factura Reservada */ END [TipoDoc], YEAR(T0.DocDate) [Year], MONTH(T0.DocDate) [Month], Day(T0.DocDate) [Day], T0.Series[Series],                         ND.SeriesName[SeriesName], T0.FolioPref[FolioPref], T0.FolioNum[FolioNum], T0.NumAtCard[NumAtCard], T0.CardCode[CardCode], T0.CardName[CardName],                         T0.DocDate[DocDate], T0.DocDueDate[DueDate], T0.TaxDate[TaxDate], T0.DocTotal[DocTotalLC], T0.DocCur[DocCurr], T0.DocRate[DocRate],                         T0.DocTotalFC[DocTotalFC], T0.DocTotalSy[DocTotalSC], T0.VatSum[VatSumLC], T0.VatSumFC[VatSumFC], T0.VatSumSy[VatSumSC],                         T0.DocTotal - T0.VatSum[DocNetSumLC]/* Importe sin IVA ML*/ , T0.DocTotalFC - T0.VatSumFC[DocNetSumFC]/* Importe sin IVA ME*/ ,                         T0.DocTotalSy - T0.VatSumSy[DocNetSumSC]/* Importe sin IVA MS*/ , T0.PaidToDate[DocPaidLC]/* Importe Pagado ML*/ ,                         T0.PaidFC[DocPaidFC]/* Importe Pagado ME*/ , T0.PaidSys[DocPaidSC]/* Importe Pagado MS*/ ,                         T0.DocTotal - T0.PaidToDate[DocBalSumLC]/* Importe Pendiente ML*/ , T0.DocTotalFC - T0.PaidFC[DocBalSumFC]/* Importe Pendiente ME*/ ,                         T0.DocTotalSy - T0.PaidSys[DocBalSumSC]/* Importe Pendiente MS*/ , T0.DiscPrcnt[DiscPrcnt], T0.DiscSum[DiscSumLC], T0.DiscSumFC[DiscSumFC],                         T0.RoundDif[RoundDifLC], T0.RoundDifFC[RoundDifFC], T0.RoundDifSy[RoundDifSC], T0.SlpCode[SlpCode], S0.SlpName[SlpName], T0.OwnerCode[OwnerCode],                         EM.LastName + EM.FirstName[EmployeeName], T0.GroupNum[PymTermCod], T0.Project[Project], T0.Indicator[Indicator], T0.LicTradNum[LicTradNum],                         T0.CreateDate[CreateDate], T0.UserSign[UserSign], T0.JrnlMemo[JrnlMemo], T0.Comments[Comments], T0.ReceiptNum[ReceiptNum], T0.CtlAccount[BPAcctCode],                         T0.WddStatus[WddStatus], T0.U_TAI_cuartacopia[CuartaCopia], T0.U_TAI_TipoVenta[TipoVenta]    FROM         OINV T0 WITH (NOLOCK) JOIN                        NNM1 ND WITH (NOLOCK) ON T0.Series = ND.Series LEFT JOIN                        OSLP S0 WITH (NOLOCK) ON T0.SlpCode = S0.SlpCode LEFT JOIN                        OHEM EM WITH (NOLOCK) ON T0.OwnerCode = EM.EmpId  WHERE     1 = 1  UNION ALL  /* Notas Crédito Cliente */ SELECT T0.ObjType[ObjType], T0.DocEntry[DocEntry], T0.TransId[TransId], T0.DocNum[DocNum], T0.DocType[DocType], T0.DocSubType[SubType],                         'NCV' [TipoDoc], YEAR(T0.DocDate) [Year], MONTH(T0.DocDate) [Month], Day(T0.DocDate) [Day], T0.Series[Series], ND.SeriesName[SeriesName],                         T0.FolioPref[FolioPref], T0.FolioNum[FolioNum], T0.NumAtCard[NumAtCard], T0.CardCode[CardCode], T0.CardName[CardName], T0.DocDate[DocDate],                         T0.DocDueDate[DueDate], T0.TaxDate[TaxDate], T0.DocTotal[DocTotalLC], T0.DocCur[DocCurr], T0.DocRate[DocRate], T0.DocTotalFC[DocTotalFC],                         T0.DocTotalSy[DocTotalSC], T0.VatSum[VatSumLC], T0.VatSumFC[VatSumFC], T0.VatSumSy[VatSumSC],                         T0.DocTotal - T0.VatSum[DocNetSumLC]/* Importe sin IVA ML*/ , T0.DocTotalFC - T0.VatSumFC[DocNetSumFC]/* Importe sin IVA ME*/ ,                         T0.DocTotalSy - T0.VatSumSy[DocNetSumSC]/* Importe sin IVA MS*/ , T0.PaidToDate[DocPaidLC]/* Importe Pagado ML*/ ,                         T0.PaidFC[DocPaidFC]/* Importe Pagado ME*/ , T0.PaidSys[DocPaidSC]/* Importe Pagado MS*/ ,                         T0.DocTotal - T0.PaidToDate[DocBalSumLC]/* Importe Pendiente ML*/ , T0.DocTotalFC - T0.PaidFC[DocBalSumFC]/* Importe Pendiente ME*/ ,                         T0.DocTotalSy - T0.PaidSys[DocBalSumSC]/* Importe Pendiente MS*/ , T0.DiscPrcnt[DiscPrcnt], T0.DiscSum[DiscSumLC], T0.DiscSumFC[DiscSumFC],                         T0.RoundDif[RoundDifLC], T0.RoundDifFC[RoundDifFC], T0.RoundDifSy[RoundDifSC], T0.SlpCode[SlpCode], S0.SlpName[SlpName], T0.OwnerCode[OwnerCode],                         EM.LastName + EM.FirstName[EmployeeName], T0.GroupNum[PymTermCod], T0.Project[Project], T0.Indicator[Indicator], T0.LicTradNum[LicTradNum],                         T0.CreateDate[CreateDate], T0.UserSign[UserSign], T0.JrnlMemo[JrnlMemo], T0.Comments[Comments], T0.ReceiptNum[ReceiptNum], T0.CtlAccount[BPAcctCode],                         T0.WddStatus[WddStatus], T0.U_TAI_cuartacopia[CuartaCopia], T0.U_TAI_TipoVenta[TipoVenta]    FROM         ORIN T0 WITH (NOLOCK) JOIN                        NNM1 ND WITH (NOLOCK) ON T0.Series = ND.Series LEFT JOIN                        OSLP S0 WITH (NOLOCK) ON T0.SlpCode = S0.SlpCode LEFT JOIN                        OHEM EM WITH (NOLOCK) ON T0.OwnerCode = EM.EmpId  WHERE     1 = 1    
CREATE VIEW dbo.TAI_VW_DetVtas  AS  SELECT        T0.ObjType[ObjType], T0.DocEntry[DocEntry], T0.TransId[TransId], T0.DocNum[DocNum], T0.DocType[DocType], T0.DocSubType[SubType], YEAR(T0.DocDate) [Year], MONTH(T0.DocDate) [Month], Day(T0.DocDate) [Day],                            STR(YEAR(T0.DocDate), 4, 0) + '-' + REPLACE(STR(MONTH(T0.DocDate), 2, 0), ' ', 0) [Periodo], T0.DocDate[DocDate], T0.DocCur[DocCurr], T0.DocRate[DocRate], T1.TargetType[TargetType], T1.ItemCode[ItemCode],                            T1.Dscription[Dscription], GI.itmsgrpcod[itmsgrpcod], GI.ItmsGrpNam[ItmsGrpNam], T1.WhsCode[WhsCode], W0.WhsName[WhsName], T1.Quantity[Quantity], T1.OpenQty[OpenQty], T1.UnitMsr[UnitMsr],                            T1.NumPerMsr[NumPerMsr], CASE T1.Currency WHEN AD.MainCurncy THEN T1.INMPrice ELSE ROUND(T1.INMPrice * T1.Rate, AD.PriceDec) END [INMPriceLC],                            CASE T1.Currency WHEN AD.MainCurncy THEN ROUND(T1.Quantity * T1.INMPrice, 0) ELSE ROUND(T1.Quantity * T1.INMPrice * T1.Rate, 0) END [INMLineTLC], T1.GrossBuyPr[GBCtoBasUntTAI], (CASE WHEN year(T0.DocDate)                            <= 2017 THEN T1.GrossBuyPr ELSE (CASE WHEN T0.U_TAI_TipoVenta IN ('ventaPuestoFundo', 'ventaCalzadaProveedor', 'ventaCostoEspecial')                            THEN T1.U_TAI_PrecioCompraO /*ELSE isnull((SELECT CC.U_TAI_CostoComercial * (case when T1.Currency='CLP' then 1 else T1.Rate end) FROM OITW CC WHERE CC.WhsCode = T1.WhsCode AND CC.ItemCode = T1.ItemCode), 0) */ ELSE                            T1.U_TAI_CostoComercial * (CASE WHEN T1.U_TAI_MonedaCosto = 'CLP' THEN 1 ELSE T1.Rate END) END) END) [GBCtoBasUnt], T1.U_TAI_ImpteComis[Comision], T1.U_TAI_descripcionad, T1.U_TAI_Interes,                            isnull(T1.U_TAI_NeoMargen, 0) NvoMargen, isnull(U_TAI_TasaInteres,0) TasaInteres, isnull(U_TAI_DiasCompra,0) as DiasCompra  FROM            OINV T0 WITH (nolock) JOIN                           INV1 T1 WITH (nolock) ON T0.DocEntry = T1.DocEntry LEFT JOIN                           OITM MI WITH (nolock) ON T1.ItemCode = MI.ItemCode LEFT JOIN                           OWHS W0 WITH (nolock) ON T1.WhsCode = W0.WhsCode LEFT JOIN                           OITB GI WITH (nolock) ON MI.ItmsGrpCod = GI.ItmsGrpCod, OADM AD WITH (nolock)  WHERE        1 = 1  UNION ALL  SELECT        T0.ObjType[ObjType], T0.DocEntry[DocEntry], T0.TransId[TransId], T0.DocNum[DocNum], T0.DocType[DocType], T0.DocSubType[SubType], YEAR(T0.DocDate) [Year], MONTH(T0.DocDate) [Month], Day(T0.DocDate) [Day],                            STR(YEAR(T0.DocDate), 4, 0) + '-' + REPLACE(STR(MONTH(T0.DocDate), 2, 0), ' ', 0) [Periodo], T0.DocDate[DocDate], T0.DocCur[DocCurr], T0.DocRate[DocRate], T1.TargetType[TargetType], T1.ItemCode[ItemCode],                            T1.Dscription[Dscription], GI.itmsgrpcod[itmsgrpcod], GI.ItmsGrpNam[ItmsGrpNam], T1.WhsCode[WhsCode], W0.WhsName[WhsName], T1.Quantity[Quantity], T1.OpenQty[OpenQty], T1.UnitMsr[UnitMsr],                            T1.NumPerMsr[NumPerMsr], CASE T1.Currency WHEN AD.MainCurncy THEN T1.INMPrice ELSE ROUND(T1.INMPrice * T1.Rate, AD.PriceDec) END [INMPriceLC],                            CASE T1.Currency WHEN AD.MainCurncy THEN ROUND(T1.Quantity * T1.INMPrice, 0) ELSE ROUND(T1.Quantity * T1.INMPrice * T1.Rate, 0) END [INMLineTLC], T1.GrossBuyPr[GBCtoBasUntTAI], (CASE WHEN year(T0.DocDate)                            <= 2017 THEN T1.GrossBuyPr ELSE (CASE WHEN T0.U_TAI_TipoVenta IN ('ventaPuestoFundo', 'ventaCalzadaProveedor', 'ventaCostoEspecial')                            THEN T1.U_TAI_PrecioCompraO /*ELSE isnull((SELECT CC.U_TAI_CostoComercial * (case when T1.Currency='CLP' then 1 else T1.Rate end) FROM OITW CC WHERE CC.WhsCode = T1.WhsCode AND CC.ItemCode = T1.ItemCode), 0) */ ELSE                            T1.U_TAI_CostoComercial * (CASE WHEN T1.U_TAI_MonedaCosto = 'CLP' THEN 1 ELSE T1.Rate END) END) END) [GBCtoBasUnt], T1.U_TAI_ImpteComis[Comision], T1.U_TAI_descripcionad, T1.U_TAI_Interes,                            isnull(T1.U_TAI_NeoMargen, 0) NvoMargen, isnull(U_TAI_TasaInteres,0) TasaInteres, isnull(U_TAI_DiasCompra,0) as DiasCompra  FROM            ORIN T0 WITH (nolock) JOIN                           RIN1 T1 WITH (nolock) ON T0.DocEntry = T1.DocEntry LEFT JOIN                           OITM MI WITH (nolock) ON T1.ItemCode = MI.ItemCode LEFT JOIN                           OWHS W0 WITH (nolock) ON T1.WhsCode = W0.WhsCode LEFT JOIN                           OITB GI WITH (nolock) ON MI.ItmsGrpCod = GI.ItmsGrpCod, OADM AD WITH (nolock)  WHERE        1 = 1  